data_market_calendar_gap_abort_v1<-function(code){if(!is.character(code)||length(code)!=1L||!grepl("^(data|desktop)_market_calendar_gap_[a-z_]+$",code))code<-"data_market_calendar_gap_boundary_failed";stop(structure(list(message=code,call=NULL,code=code),class=c("spot_data_market_calendar_gap_error_v1","error","condition")))}
new_data_market_calendar_gap_service_v1<-function(project_root,context){root<-normalizePath(project_root,winslash="/",mustWork=TRUE);python<-Sys.which("python3");cli<-file.path(root,"scripts","desktop_market_calendar_gap_catalog.py");space<-runtime_data_space_path(context);ctx<-list(tenant_id=context$tenant_id,user_id=context$user_id,data_space_id=context$data_space_id);read<-function(listings,fx_demands,start,end){o<-suppressWarnings(system2(python,c("-B","-E","-s",shQuote(cli)),stdout=TRUE,stderr=TRUE,input=as.character(jsonlite::toJSON(list(context=ctx,data_space_path=space,listings=listings,fx_demands=fx_demands,start_date=start,end_date=end),auto_unbox=TRUE,null="null",digits=NA))));s<-attr(o,"status");if(is.null(s))s<-0L;p<-tryCatch(jsonlite::fromJSON(tail(o,1L),simplifyVector=FALSE),error=function(e)NULL);if(is.null(p)||s!=0L||!identical(p$status,"completed"))data_market_calendar_gap_abort_v1(if(is.null(p$code))"data_market_calendar_gap_boundary_failed"else p$code);p$result};structure(list(read=read,provider_access=FALSE,history_write=FALSE,canonical_write=FALSE),class=c("spot_data_market_calendar_gap_service_v1","list"))}
